<script setup lang="ts">
import { computed,onMounted,reactive,ref } from "vue";import { Pige360SessionClient,type ApiProblem } from "@pige360/auth";type Row=Record<string,any>;const api=new Pige360SessionClient();const ready=ref(false),auth=ref(false),busy=ref(false),error=ref(""),notice=ref(""),email=ref(""),password=ref("");const tenants=ref<Row[]>([]),status=ref<Row>({}),audit=ref<Row[]>([]),support=ref<Row[]>([]),selected=ref<Row|null>(null),apps=ref<Row>({entitlements:[],manifests:[],builds:[],releases:[]}),branding=ref<Row>({});const form=reactive({code:"",legal_name:"",trade_name:"",hostname:"",owner_email:"",owner_password:""});const supportForm=reactive({reason:"",ticket:"",minutes:30});const appProduct=ref("family-mobile");const platform=ref("pwa");
function msg(e:unknown){const p=(e as Error&{problem?:ApiProblem})?.problem;return p?.detail||(e instanceof Error?e.message:"Erro inesperado");}async function load(){const [t,s,a,ss]=await Promise.all([api.request<Row>("/platform/tenants"),api.request<Row>("/platform/status"),api.request<Row>("/platform/audit?limit=50"),api.request<Row>("/platform/support-sessions?active_only=true")]);tenants.value=t.items||[];status.value=s;audit.value=a.items||[];support.value=ss.items||[];if(selected.value){const fresh=tenants.value.find(x=>x.id===selected.value?.id);if(fresh)selected.value=fresh;await loadTenant();}}async function loadTenant(){if(!selected.value)return;[apps.value,branding.value]=await Promise.all([api.request<Row>(`/platform/tenants/${selected.value.id}/apps`),api.request<Row>(`/platform/tenants/${selected.value.id}/branding`)]);}async function boot(){try{await api.initialize();auth.value=!!api.tokens;if(auth.value)await load();}catch(e){error.value=msg(e);}finally{ready.value=true;}}async function login(){try{await api.login(email.value,password.value);if(api.claims()?.plane!=='platform')throw new Error('Use uma conta do Control Plane.');auth.value=true;await load();}catch(e){error.value=msg(e);}}async function logout(){await api.logout();auth.value=false;}async function createTenant(){busy.value=true;try{await api.request('/platform/tenants',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(form)});notice.value='Tenant provisionado.';Object.assign(form,{code:"",legal_name:"",trade_name:"",hostname:"",owner_email:"",owner_password:""});await load();}catch(e){error.value=msg(e);}finally{busy.value=false;}}async function choose(t:Row){selected.value=t;await loadTenant();}async function createSupport(){if(!selected.value)return;try{await api.request(`/platform/tenants/${selected.value.id}/support-sessions`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(supportForm)});notice.value='Sessão de suporte auditada criada.';await load();}catch(e){error.value=msg(e);}}async function entitlement(){if(!selected.value)return;try{await api.request(`/platform/tenants/${selected.value.id}/apps/entitlements`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({app_product:appProduct.value,state:'active',contract_reference:'console'})});notice.value='Entitlement atualizado.';await loadTenant();}catch(e){error.value=msg(e);}}
async function manifestAndBuild(){if(!selected.value)return;const brandVersion=branding.value.active_version;if(!brandVersion){error.value='Publique o branding do tenant antes de gerar aplicativos.';return;}const domain=selected.value.domains?.find((d:Row)=>d.is_canonical)?.hostname||selected.value.domains?.[0]?.hostname;if(!domain){error.value='Tenant sem domínio provisionado.';return;}const slug=selected.value.code.replace(/[^a-z0-9]/g,'');const product=appProduct.value;const idProduct=product.replace(/-mobile$/,'').replace(/-/g,'.');try{const mf=await api.request<Row>(`/platform/tenants/${selected.value.id}/apps/manifests`,{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':`manifest-${crypto.randomUUID()}`},body:JSON.stringify({tenant_code:selected.value.code,brand_version:brandVersion,release_channel:'stable',apps:{[product]:{enabled:true,display_name:`${selected.value.trade_name} ${product}`,identifier:`br.com.${slug}.${idProduct}`,api_url:`https://${domain}`,web_url:`https://${domain}`,update_url:`https://${domain}/apps`,features:{finance:true,attendance:true},signing:{}}},metadata:{created_from:'platform-console'}})});const build=await api.request<Row>(`/platform/tenants/${selected.value.id}/apps/builds`,{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':`build-${crypto.randomUUID()}`},body:JSON.stringify({manifest_id:mf.id,platforms:[platform.value],products:[product]})});notice.value=`Build ${build.id} enfileirado.`;await loadTenant();}catch(e){error.value=msg(e);}}
onMounted(boot);
</script>
<template><div v-if="!ready" class="center">Inicializando Control Plane…</div><div v-else-if="!auth" class="login-page platform-login"><form class="login-card" @submit.prevent="login"><div class="mark">◈</div><span class="eyebrow">PIGE360</span><h1>Console Global</h1><p>Administração da plataforma, tenants e distribuição.</p><label>E-mail<input v-model="email" type="email" required></label><label>Senha<input v-model="password" type="password" required></label><p v-if="error" class="flash error">{{error}}</p><button class="primary">Entrar</button></form></div><div v-else class="console"><aside><div class="brand"><div class="mark">◈</div><div><strong>PIGE360</strong><small>Control Plane</small></div></div><button v-for="t in tenants" :key="t.id" :class="{active:selected?.id===t.id}" @click="choose(t)"><strong>{{t.trade_name}}</strong><small>{{t.status}}</small></button><button class="logout" @click="logout">Sair</button></aside><main><div v-if="error" class="flash error">{{error}}</div><div v-if="notice" class="flash success">{{notice}}</div><header><div><span class="eyebrow">PIGE360</span><h1>{{selected?selected.trade_name:'Visão global'}}</h1></div><button class="ghost-dark" @click="load">Atualizar</button></header><section class="metrics"><article><span>Tenants</span><strong>{{status.tenants?.total||0}}</strong><small>{{status.tenants?.active||0}} ativos</small></article><article><span>Domínios</span><strong>{{status.domains||0}}</strong><small>hosts registrados</small></article><article><span>Builds na fila</span><strong>{{status.builds?.queued||0}}</strong><small>{{status.builds?.building||0}} executando</small></article><article><span>Suporte</span><strong>{{status.active_support_sessions||0}}</strong><small>sessões ativas</small></article></section><section v-if="!selected" class="grid two"><form class="panel form" @submit.prevent="createTenant"><h2>Provisionar tenant</h2><label>Código<input v-model="form.code" pattern="[a-z0-9-]+" required></label><label>Razão social<input v-model="form.legal_name" required></label><label>Nome comercial<input v-model="form.trade_name" required></label><label>Hostname inicial<input v-model="form.hostname" placeholder="admin.escola.com.br" required></label><label>Administrador inicial<input v-model="form.owner_email" type="email" required></label><label>Senha inicial<input v-model="form.owner_password" type="password" minlength="10" required></label><button class="primary" :disabled="busy">Provisionar</button></form><div class="panel"><h2>Auditoria global</h2><div class="list-row" v-for="a in audit.slice(0,15)" :key="a.id"><div><strong>{{a.action}} · {{a.aggregate_type}}</strong><span>{{a.tenant_id||'platform'}} · {{a.correlation_id}}</span></div><small>{{a.created_at}}</small></div></div></section><template v-else><section class="grid two"><div class="panel"><h2>Tenant</h2><dl class="facts"><div><dt>Código</dt><dd>{{selected.code}}</dd></div><div><dt>Status</dt><dd>{{selected.status}}</dd></div><div><dt>Branding</dt><dd>v{{branding.active_version||0}} · {{branding.state}}</dd></div><div v-for="d in selected.domains" :key="d.id"><dt>Domínio</dt><dd>{{d.hostname}} · {{d.status}}</dd></div></dl></div><form class="panel form" @submit.prevent="createSupport"><h2>Sessão de suporte</h2><label>Motivo<textarea v-model="supportForm.reason" minlength="10" required></textarea></label><label>Ticket<input v-model="supportForm.ticket"></label><label>Duração (min)<input v-model.number="supportForm.minutes" type="number" min="5" max="120"></label><button class="primary">Criar sessão auditada</button></form></section><section class="panel"><div class="section-title"><h2>App Factory</h2><span>{{apps.builds?.length||0}} builds</span></div><div class="app-actions"><select v-model="appProduct"><option v-for="p in ['family-mobile','teacher-mobile','student-mobile','admin-mobile','pos-mobile','kiosk','timeclock','desktop-admin','pos-desktop','pwa']" :key="p">{{p}}</option></select><select v-model="platform"><option v-for="p in ['pwa','android-apk','android-aab','ios-app','ios-xcarchive','ios-ipa-unsigned','windows-x64','windows-x86','linux-x64','linux-arm64','macos-intel','macos-apple']" :key="p">{{p}}</option></select><button class="ghost-dark" @click="entitlement">Ativar entitlement</button><button class="primary" @click="manifestAndBuild">Gerar manifesto + build</button></div><div class="list-row" v-for="b in apps.builds" :key="b.id"><div><strong>{{b.id}}</strong><span>{{b.status||b.state}} · {{b.created_at}}</span></div><small>{{b.jobs?.length||0}} jobs</small></div></section><section class="panel"><h2>Releases</h2><div class="list-row" v-for="r in apps.releases" :key="r.id"><div><strong>{{r.version}} · {{r.channel}}</strong><span>{{r.state}}</span></div><small>{{r.created_at}}</small></div><p v-if="!apps.releases?.length" class="empty">Nenhuma release criada.</p></section></template></main></div></template>
